function validate([num]) {
  if (typeof num !== 'string') return 'num must be a string.';
  if (num.length < 2 || num.length > 100000) return 'num needs 2 to 100000 characters.';
  if (num.length % 2 !== 0) return 'num must have even length.';
  if (!/^[0-9?]*$/.test(num)) return "num may contain only digits and '?'.";
  return null;
}

