  const half = num.length / 2;
  let leftSum = 0;
  let rightSum = 0;
  let leftMarks = 0;
  let rightMarks = 0;

  for (let i = 0; i < num.length; i++) {
    const isLeft = i < half;
    if (num[i] === '?') {
      if (isLeft) {
        leftMarks++;
      } else {
        rightMarks++;
      }
    } else if (isLeft) {
      leftSum += Number(num[i]);
    } else {
      rightSum += Number(num[i]);
    }
  }

  if ((leftMarks + rightMarks) % 2 === 1) {
    return true;
  }
  return 2 * (leftSum - rightSum) !== 9 * (rightMarks - leftMarks);
}

