function sumGame(num) {
  // Full minimax over (marks left on each side, current left-minus-right difference).
  const half = num.length / 2;
  let l = 0, r = 0, d = 0;
  for (let i = 0; i < num.length; i++) {
    if (num[i] === '?') { if (i < half) l++; else r++; }
    else d += (i < half ? 1 : -1) * (num.charCodeAt(i) - 48);
  }
  const total = l + r;
  const memo = new Map();
  const aliceWins = (a, b, diff) => {
    if (a === 0 && b === 0) return diff !== 0;
    const key = a + ',' + b + ',' + diff;
    if (memo.has(key)) return memo.get(key);
    const aliceToMove = (total - a - b) % 2 === 0;
    const results = [];
    for (let digit = 0; digit <= 9; digit++) {
      if (a > 0) results.push(aliceWins(a - 1, b, diff + digit));
      if (b > 0) results.push(aliceWins(a, b - 1, diff - digit));
    }
    const value = aliceToMove ? results.some(x => x) : results.every(x => x);
    memo.set(key, value);
    return value;
  };
  return aliceWins(l, r, d);
}

