function generate(rand, size) {
  const n = size === 'large' ? 2 * (4000 + Math.floor(rand() * 1001)) : 2 * (1 + Math.floor(rand() * 5));
  const half = n / 2;
  const markChance = size === 'large' ? [0.002, 0.05, 0.5][Math.floor(rand() * 3)] : rand() * 0.8;
  const chars = Array.from({ length: n }, () => rand() < markChance ? '?' : Math.floor(rand() * 10));
  // Half of the inputs are tuned so that Bob wins: an even number of marks and left - right = 9 * (right marks - left marks) / 2.
  if (rand() < 0.5) {
    let leftMarks = 0, rightMarks = 0;
    for (let i = 0; i < n; i++) if (chars[i] === '?') { if (i < half) leftMarks++; else rightMarks++; }
    if ((leftMarks + rightMarks) % 2 === 1) {
      const i = Math.floor(rand() * n);
      const delta = chars[i] === '?' ? -1 : 1;
      chars[i] = chars[i] === '?' ? 0 : '?';
      if (i < half) leftMarks += delta; else rightMarks += delta;
    }
    let diff = 0;
    for (let i = 0; i < n; i++) if (chars[i] !== '?') diff += i < half ? chars[i] : -chars[i];
    // need is how much left - right must still grow; raising a left digit or lowering a right digit grows it.
    let need = 9 * (rightMarks - leftMarks) / 2 - diff;
    for (let i = 0; i < n && need !== 0; i++) {
      if (chars[i] === '?') continue;
      const grow = (i < half) === (need > 0);
      const step = Math.min(Math.abs(need), grow ? 9 - chars[i] : chars[i]);
      chars[i] += grow ? step : -step;
      need -= Math.sign(need) * step;
    }
  }
  return [chars.join('')];
}
